E["quest:94270"] = {t="quest",n="Craftsman's Writ: Steel Weapon Chain",z="general",s="A customer has penned a trade note requesting a steel weapon chain, complete with payment terms and delivery instructions. You hold a transferable agreement that lets any bearer provide the forged metalwork and collect the trade fee.",h="A customer has penned a trade note requesting a steel weapon chain, complete with payment terms and delivery...",sec={{t="An Order for Steel",b="A customer has drawn up a trade order in faded ink, asking for one steel weapon chain. The note details the payment offered and directs you to a drop-off spot marked on your map. Because the agreement is transferable, whoever holds the paper can finish the trade.",sp=0}},faq={{q="What item does the writ ask for?",a="The note asks for a single steel weapon chain.",al={"what item is needed","writ item requested"}},{q="Can someone else deliver the order?",a="Anyone carrying the document can fulfill the order, as the note is marked transferable.",al={"who can use this writ","is the writ tradeable"}},{q="Where do you deliver the finished chain?",a="The order must be taken to the delivery spot marked on your map.",al={"where to bring the chain","writ drop off location"}},{q="Do you need to hold the writ to finish the delivery?",a="You must carry the writ with you to conclude the trade and receive payment.",al={"must i keep the writ","do i need the paper"}}},ang={["profession:Blacksmithing"]="As a blacksmith, you can forge the steel weapon chain yourself, turning your metalwork directly into trade payment."},kw={"blacksmithing","craftsman's writ","delivery","steel weapon chain","trade","writ"},m={id=94270},src={"In-game quest text: Craftsman's Writ: Steel Weapon Chain"},fv=true}
